1	export type Item = {
2	  type: string;
3	  material?: string;
4	  cursed?: boolean;
5	  enchantment?: number;
6	};
7	
8	export type QuoteStep = {
9	  op: string;
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type Incident = {
19	  cause: string;
20	  damages: Damage[];
21	};
22	
23	export type ClaimStep = {
24	  op: string;
25	  policy: number;
26	  incident: Incident;
27	};
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export type Customer = {
32	  yearsWithMHPCO: number;
33	};
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type QuoteResult = {
41	  premium: number;
42	};
43	
44	export type ClaimResult = {
45	  payout: number;
46	  remainingCap: number;
47	};
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export type ScenarioOutcome = {
52	  results: StepResult[];
53	};
54	
55	const PROCESSING_FEE = 5;
56	
57	const BASE_PREMIUMS: Record<string, number> = {
58	  sword: 100,
59	  amulet: 60,
60	  staff: 80,
61	  potion: 40,
62	  rune: 25,
63	  moonstone: 25,
64	};
65	
66	const FIRST_INSURANCE_PERCENT = 10;
67	
68	// Multiply before dividing: `amount * 1.1` drifts (115.00000000000001) and
69	// Math.ceil turns the drift into a whole extra gold piece. The spec requires
70	// intermediates to stay exact, so every percentage goes through here.
71	const PERCENT_WHOLE = 100;
72	
73	const percentOf = (amount: number, percent: number): number =>
74	  (amount * percent) / PERCENT_WHOLE;
75	
76	// Rounding always favours MHPCO: premiums round up, payouts round down.
77	const roundPremium = (amount: number): number => Math.ceil(amount);
78	
79	const basePremiumOfType = (type: string): number => BASE_PREMIUMS[type];
80	
81	const BLOCK_SIZE = 3;
82	const BLOCK_BASE_PREMIUM = 60;
83	
84	const countByType = (items: Item[]): Map<string, number> => {
85	  const counts = new Map<string, number>();
86	  for (const item of items) {
87	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
88	  }
89	  return counts;
90	};
91	
92	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
93	
94	// A building block is exactly 3 alike components. Blocks are only offered on
95	// components, never on main items, and only at exactly 3 — 4 runes are priced
96	// per item, not as a block plus one.
97	const formsBuildingBlock = (type: string, count: number): boolean =>
98	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE;
99	
100	// A group of alike items is priced as a building block if it forms one, and
101	// per item otherwise.
102	const groupBasePremiumOf = (type: string, count: number): number =>
103	  formsBuildingBlock(type, count)
104	    ? BLOCK_BASE_PREMIUM
105	    : count * basePremiumOfType(type);
106	
107	// The policy base premium is the sum of the base premiums of each group of
108	// alike items.
109	const policyBasePremiumOf = (items: Item[]): number =>
110	  [...countByType(items)].reduce(
111	    (total, [type, count]) => total + groupBasePremiumOf(type, count),
112	    0,
113	  );
114	
115	// Item-specific surcharges are additive percentages of the affected item's OWN
116	// base premium — they never compound with each other, and never apply to the
117	// policy total.
118	const CURSE_PERCENT = 50;
119	const HIGH_ENCHANTMENT_PERCENT = 30;
120	const HIGH_ENCHANTMENT_THRESHOLD = 5;
121	
122	const isCursed = (item: Item): boolean => item.cursed === true;
123	
124	const isHighlyEnchanted = (item: Item): boolean =>
125	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
126	
127	const surchargePercentOf = (item: Item): number =>
128	  (isCursed(item) ? CURSE_PERCENT : 0) +
129	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_PERCENT : 0);
130	
131	const itemSurchargesOf = (items: Item[]): number =>
132	  items.reduce(
133	    (total, item) =>
134	      total + percentOf(basePremiumOfType(item.type), surchargePercentOf(item)),
135	    0,
136	  );
137	
138	const LOYALTY_PERCENT = 20;
139	const LOYALTY_THRESHOLD_YEARS = 2;
140	const FOLLOW_UP_CONTRACT_PERCENT = 15;
141	
142	const isLongStanding = (customer: Customer): boolean =>
143	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
144	
145	// Policy-wide modifiers are additive percentages of the policy base premium:
146	// they never compound with each other. A discount is simply a negative
147	// percentage, so surcharges and discounts sum in a single list.
148	const policyModifierPercentOf = (
149	  customer: Customer,
150	  isFollowUpContract: boolean,
151	): number =>
152	  FIRST_INSURANCE_PERCENT +
153	  (isLongStanding(customer) ? -LOYALTY_PERCENT : 0) +
154	  (isFollowUpContract ? -FOLLOW_UP_CONTRACT_PERCENT : 0);
155	
156	const processQuote = (
157	  step: QuoteStep,
158	  customer: Customer,
159	  isFollowUpContract: boolean,
160	): QuoteResult => {
161	  const basePremium = policyBasePremiumOf(step.items);
162	  const policyModifiers = percentOf(
163	    basePremium,
164	    policyModifierPercentOf(customer, isFollowUpContract),
165	  );
166	
167	  return {
168	    premium: roundPremium(
169	      basePremium +
170	        itemSurchargesOf(step.items) +
171	        policyModifiers +
172	        PROCESSING_FEE,
173	    ),
174	  };
175	};
176	
177	const INSURANCE_VALUES: Record<string, number> = {
178	  sword: 1000,
179	  amulet: 600,
180	  staff: 800,
181	  potion: 400,
182	  rune: 250,
183	  moonstone: 250,
184	};
185	
186	const DEDUCTIBLE = 100;
187	const CAP_MULTIPLIER = 2;
188	
189	// Rounding always favours MHPCO: payouts round down.
190	const roundPayout = (amount: number): number => Math.floor(amount);
191	
192	const insuranceSumOf = (items: Item[]): number =>
193	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
194	
195	// A policy is created by a quote step and accumulates claims against its cap.
196	type Policy = {
197	  items: Item[];
198	  remainingCap: number;
199	};
200	
201	const isClaimStep = (step: Step): step is ClaimStep => step.op === "claim";
202	
203	// Distinct from HIGH_ENCHANTMENT_THRESHOLD (5) above, which bands an item as
204	// risky enough to carry a premium SURCHARGE. This higher bar marks an item as
205	// volatile: MHPCO caps its exposure by reimbursing only half the damage. Two
206	// unrelated rules that happen to both read the enchantment level — they are
207	// free to move independently, so they get independent names and constants.
208	const VOLATILE_ENCHANTMENT_THRESHOLD = 8;
209	const VOLATILE_REIMBURSEMENT_PERCENT = 50;
210	
211	const isVolatilelyEnchanted = (item: Item): boolean =>
212	  (item.enchantment ?? 0) >= VOLATILE_ENCHANTMENT_THRESHOLD;
213	
214	const DRAGON_MATERIAL = "dragon";
215	const FULL_REIMBURSEMENT_PERCENT = 100;
216	
217	const isDragonMaterial = (item: Item): boolean =>
218	  item.material === DRAGON_MATERIAL;
219	
220	// Special clauses in precedence order. Dragon material is fully reimbursed, but
221	// where an item is also volatilely enchanted the 50 % rule wins.
222	//
223	// NOTE: the dragon branch is currently indistinguishable from the default —
224	// full reimbursement is what an ordinary item gets anyway, and every spec
225	// example pairing dragon material with enchantment >= 8 is decided by the
226	// volatile rule above it. No test constrains this branch. It is written out
227	// because the spec states it as a rule, so that it is represented rather than
228	// accidental if the default ever stops being full reimbursement.
229	const reimbursementPercentFor = (item: Item): number => {
230	  if (isVolatilelyEnchanted(item)) return VOLATILE_REIMBURSEMENT_PERCENT;
231	  if (isDragonMaterial(item)) return FULL_REIMBURSEMENT_PERCENT;
232	  return FULL_REIMBURSEMENT_PERCENT;
233	};
234	
235	// The deductible is withheld once per damaged item, so it is subtracted per
236	// damage entry rather than once from the incident total. Special clauses reduce
237	// the reimbursement first; the deductible always comes last.
238	const netPayableFor = (damage: Damage, item: Item): number =>
239	  percentOf(damage.amount, reimbursementPercentFor(item)) - DEDUCTIBLE;
240	
241	// The insured item a damage entry refers to. The cast holds only while every
242	// damage entry is guaranteed to name an insured type; the "claim for an item
243	// not part of the policy" test will force this to return undefined honestly.
244	const insuredItemFor = (damage: Damage, policy: Policy): Item =>
245	  policy.items.find((item) => item.type === damage.itemType) as Item;
246	
247	const totalReimbursementFor = (incident: Incident, policy: Policy): number =>
248	  incident.damages.reduce(
249	    (total, damage) => total + netPayableFor(damage, insuredItemFor(damage, policy)),
250	    0,
251	  );
252	
253	// Pure: reports what the claim pays and what the cap would be left at. The
254	// caller owns writing the depleted cap back to the policy.
255	const processClaim = (step: ClaimStep, policy: Policy): ClaimResult => {
256	  const payout = roundPayout(totalReimbursementFor(step.incident, policy));
257	
258	  return { payout, remainingCap: policy.remainingCap - payout };
259	};
260	
261	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
262	  const policies = new Map<number, Policy>();
263	  let quotesSoFar = 0;
264	
265	  const results = scenario.steps.map((step, index): StepResult => {
266	    if (isClaimStep(step)) {
267	      const policy = policies.get(step.policy) as Policy;
268	      const result = processClaim(step, policy);
269	      // Claims deplete the cap for every later claim against this policy.
270	      policy.remainingCap = result.remainingCap;
271	      return result;
272	    }
273	
274	    const result = processQuote(step, scenario.customer, quotesSoFar > 0);
275	    quotesSoFar += 1;
276	    policies.set(index, {
277	      items: step.items,
278	      remainingCap: CAP_MULTIPLIER * insuranceSumOf(step.items),
279	    });
280	    return result;
281	  });
282	
283	  return { results };
284	};
